$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$out = Join-Path (Get-Location) 'deliverables/graduation-paper/Graduation_Project_Presentation_2026-10-27.pptx'
$tmp = Join-Path (Get-Location) 'tmp/pptx-build'
if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force}
New-Item -ItemType Directory -Force -Path $tmp | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $tmp '_rels'),(Join-Path $tmp 'ppt'),(Join-Path $tmp 'ppt/_rels'),(Join-Path $tmp 'ppt/slides'),(Join-Path $tmp 'ppt/slides/_rels'),(Join-Path $tmp 'ppt/slideLayouts'),(Join-Path $tmp 'ppt/slideLayouts/_rels'),(Join-Path $tmp 'ppt/slideMasters'),(Join-Path $tmp 'ppt/slideMasters/_rels'),(Join-Path $tmp 'ppt/theme') | Out-Null
function W($p,$s){[IO.File]::WriteAllText($p,$s,(New-Object Text.UTF8Encoding($false)))}
function E($s){[Security.SecurityElement]::Escape([string]$s)}
$slides=@(
 @{t='Graduation Registration and Attendance'; sub='Using Browser-Based Face Recognition'; body='Mae Fah Luang University`nGraduation System Project`n`nThitirat Chuaypetch  |  Nattanicha Bunchuen  |  Kwankamolsri Jandee`nTeerasak Jeefu  |  Nataporn Dibdee'; accent='00A7A7'},
 @{t='Project Overview'; sub='One workflow for preparation and attendance'; body='The system connects graduate registration, ceremony preferences, food allergy reporting, face enrollment, and attendance operations.`n`nIt separates student-facing forms from administrator tools while keeping records in one MongoDB-backed application.'; accent='00A7A7'},
 @{t='What the System Supports'; sub='Core user workflows'; body='STUDENT WORKFLOW`nเน€เธยเนยเธเน€เธย Employment questionnaire`nเน€เธยเนยเธเน€เธย Personal, academic, and address information`nเน€เธยเนยเธเน€เธย Ceremony participation and certificate delivery`nเน€เธยเนยเธเน€เธย Assistance and food allergy details`nเน€เธยเนยเธเน€เธย Reference photo enrollment`n`nADMIN WORKFLOW`nเน€เธยเนยเธเน€เธย Search, filters, editing, summaries`nเน€เธยเนยเธเน€เธย Allergy roster and attendance operations'; accent='F2B134'},
 @{t='System Architecture'; sub='Browser, API, database, and identity services'; body='Student browser  เน€เธยเธขยเนโฌย  Vue frontend  เน€เธยเธขยเนโฌย  Node.js / Express API  เน€เธยเธขยเนโฌย  MongoDB`n`nAdministrator browser  เน€เธยเธขยเนโฌย  roster and camera operations`n`nIdentity integration supports authentication and permission boundaries.`n`nFace matching is performed in the administrator browser; the backend validates and stores attendance receipts.'; accent='00A7A7'},
 @{t='Face Enrollment and Matching'; sub='How an attendance decision is produced'; body='1  Capture guidance checks face count, position, brightness, and image quality.`n2  The reference photograph is stored separately from attendance receipts.`n3  The administrator scanner prepares descriptors from enrolled images.`n4  A camera descriptor is compared with the gallery using Euclidean distance.`n5  The selected activity receipt is written only after backend validation.'; accent='F2B134'},
 @{t='Data and Attendance Design'; sub='Separate data for separate purposes'; body='Graduate_Registration stores identity, contact, academic, ceremony, allergy, questionnaire, and face metadata.`n`nlatestCheckIns.rehearsal and latestCheckIns.ceremony keep the latest receipt for each activity.`n`nThis prevents camera frames from replacing the enrollment photograph and keeps rehearsal attendance separate from ceremony attendance.'; accent='00A7A7'},
 @{t='Verification Results'; sub='What was verified in the reviewed project snapshot'; body='23 frontend tests passed.`n9 backend tests passed.`n`nVerified areas included administrative editing, permission navigation, check-in validation, duplicate receipt handling, attendance pagination, and preservation of unrelated registration data.`n`nThe automatic scanner suite was blocked during initialization because face-api.js was unavailable.'; accent='F2B134'},
 @{t='Limitations and Next Steps'; sub='Important boundaries before live deployment'; body='เน€เธยเนยเธเน€เธย Restore a consistent scanner and recognition-helper interface.`nเน€เธยเนยเธเน€เธย Align client and server acceptance thresholds.`nเน€เธยเนยเธเน€เธย Re-run browser recognition tests with the required dependency.`nเน€เธยเนยเธเน€เธย Evaluate false acceptance, false rejection, latency, and throughput using a consented labeled dataset.`nเน€เธยเนยเธเน€เธย Review authorization shortcuts, photo retention, health-related notes, and staff review procedures.'; accent='00A7A7'},
 @{t='Conclusion'; sub='A functional graduation operations foundation'; body='The project brings registration preparation and attendance administration into one application.`n`nIt provides a clear student workflow, practical administrator tools, and separated attendance data.`n`nThe current evidence supports selected workflow and persistence behaviors. Live biometric performance still requires integration repair and formal evaluation.'; accent='F2B134'}
)
