function Tx($x,$y,$w,$h,$txt,$size,$color,$bold='0'){$paras='';foreach($line in ($txt -split "`n")){if($line -eq ''){$paras+='<a:p><a:endParaRPr lang="en-US"/></a:p>'}else{$paras+="<a:p><a:r><a:rPr lang=`"en-US`" sz=`"$size`" b=`"$bold`"><a:solidFill><a:srgbClr val=`"$color`"/></a:solidFill><a:latin typeface=`"Aptos`"/></a:rPr><a:t>$(E $line)</a:t></a:r><a:endParaRPr lang=`"en-US`" sz=`"$size`"/></a:p>"}};return "<p:sp><p:nvSpPr><p:cNvPr id=`"$([int]($x+$y))`" name=`"Text`"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:xfrm><a:off x=`"$x`" y=`"$y`"/><a:ext cx=`"$w`" cy=`"$h`"/></a:xfrm><a:prstGeom prst=`"rect`"><a:avLst/></a:prstGeom></p:spPr><p:txBody><a:bodyPr wrap=`"square`"/><a:lstStyle/>$paras</p:txBody></p:sp>"}
for($i=0;$i -lt $slides.Count;$i++){ $s=$slides[$i];$n=$i+1;$sh='<p:spTree><p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/><p:sp><p:nvSpPr><p:cNvPr id="2" name="Background"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr><a:solidFill><a:srgbClr val="102A43"/></a:solidFill><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:xfrm><a:off x="0" y="0"/><a:ext cx="12192000" cy="6858000"/></a:xfrm></p:spPr></p:sp>';$sh+=Tx 720 620 10800 500 $s.t 3000 'FFFFFF' '1';$sh+=Tx 720 1180 10800 350 $s.sub 1500 $s.accent '1';$sh+=Tx 900 1900 10100 3900 $s.body 1900 'F4F7FA' '0';$sh+='</p:spTree>';W (Join-Path $tmp "ppt/slides/slide$n.xml") ("<?xml version=`"1.0`" encoding=`"UTF-8`"?><p:sld xmlns:a=`"http://schemas.openxmlformats.org/drawingml/2006/main`" xmlns:p=`"http://schemas.openxmlformats.org/presentationml/2006/main`" xmlns:r=`"http://schemas.openxmlformats.org/officeDocument/2006/relationships`"><p:cSld name=`"Slide $n`">$sh</p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>");W (Join-Path $tmp "ppt/slides/_rels/slide$n.xml.rels") '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/></Relationships>' }
